const raw=$json.incident_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
const notifications=Array.isArray(ctx?.notifications)?ctx.notifications:[];
let gate=ctx?.reliability_gate ?? {};
if(typeof gate==='string'){try{gate=JSON.parse(gate)}catch{gate={allowed:false}}}
const enabled=$env.INCIDENT_SLACK_ENABLED==='true';
const channel=String($env.INCIDENT_SLACK_CHANNEL_ID ?? '').trim();
const clean=v=>String(v??'').replace(/[<>]/g,'').replace(/[\u0000-\u001f\u007f]/g,' ').slice(0,700);
const lines=['*Agent V2 incident alert*'];
for(const item of notifications.slice(0,20)){
  const a=item?.alert ?? {};
  const severity=clean(a.severity ?? 'alert').toUpperCase();
  const component=clean(a.component_key ?? a.component ?? 'runtime');
  const kind=clean(a.alert_type ?? a.alert_key ?? a.status ?? 'attention_required');
  const detail=clean(a.message ?? a.reason ?? '');
  lines.push('• ['+severity+'] '+component+' — '+kind+(detail?' — '+detail:''));
}
let text=lines.join('\n');
if(text.length>10000) text=text.slice(0,9990)+'…';
const shouldSend=enabled && gate?.allowed===true && notifications.length>0 && channel.length>0;
return {
  incident_context:ctx,
  notifications,
  fingerprints:notifications.map(x=>x?.fingerprint).filter(Boolean),
  slack_payload:{channel_id:channel,text},
  should_send:shouldSend,
  event_id:'EVT-INCIDENT-'+String(Math.floor(Date.now()/300000)),
  skip_reason:shouldSend?null:(!enabled?'INCIDENT_SLACK_DISABLED':(notifications.length===0?'NO_PENDING_ALERTS':(gate?.allowed!==true?'INCIDENT_CIRCUIT_OPEN':'INCIDENT_DESTINATION_MISSING')))
};
